[``` \begin{aligned} [$left] \amp= [$right]\\ [$leftsol[0]] \amp= [$rightsol[0]]\\ [$leftsol[1]] \amp= [$rightsol[1]]\\ [$leftsol[2]] \amp= [$rightsol[2]] \end{aligned} ```]
